"});\n  return K;\n}\n\n// tipi di rail: profilo in [lunghezza, altezza all'inizio, altezza alla fine, forma]\nfunction railSp",
"ec(type, R) {\n  switch (type) {\n    case 'box': return { kind: 'box', hw: 0.27, L: 9 + R() * 4, h0: 0.45, h1: 0.45, entr",
